class Trie {
  root = new Map();
  insert(w) {
    let n = this.root;
    for (const c of w) { if (!n.has(c)) n.set(c, new Map()); n = n.get(c); }
    n.set('$', true);
  }
  #walk(w) { let n = this.root; for (const c of w) { n = n.get(c); if (!n) return null; } return n; }
  search(w) { return this.#walk(w)?.has('$') ?? false; }
  startsWith(p) { return this.#walk(p) !== null; }
}
const t = new Trie();
t.insert('apple'); t.insert('app');
console.log(t.search('app'), t.search('appl'), t.startsWith('appl'), t.search('apples'));

const root = { c: {}, n: 0 };
function add(w) {
  let x = root;
  for (const ch of w) { x = x.c[ch] ??= { c: {}, n: 0 }; x.n++; }
}
function count(p) {
  let x = root;
  for (const ch of p) { x = x.c[ch]; if (!x) return 0; }
  return x.n;
}
['car', 'cart', 'cat', 'dog'].forEach(add);
console.log(count('ca'), count('car'), count('d'), count('x'));

