function merge(iv) {
  const s = iv.toSorted((a, b) => a[0] - b[0]);
  const out = [];
  for (const [st, en] of s) {
    const last = out.at(-1);
    if (last && st <= last[1]) last[1] = Math.max(last[1], en);
    else out.push([st, en]);
  }
  return out;
}
console.log(JSON.stringify(merge([[8, 10], [1, 3], [2, 6], [6, 7], [15, 18]])));

function rooms(iv) {
  const ev = [];
  for (const [s, e] of iv) ev.push([s, 1], [e, -1]);
  ev.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  let cur = 0, best = 0;
  for (const [, d] of ev) { cur += d; best = Math.max(best, cur); }
  return best;
}
console.log(rooms([[0, 30], [5, 10], [15, 20]]), rooms([[1, 5], [5, 8]]), rooms([[1, 4], [2, 5], [3, 6]]));
